// MOTOR DE MACHINE LEARNING (TF-IDF + COSINE + LEVENSHTEIN)
// ============================================================================
const STOPWORDS_ES = new Set([
  "el", "la", "los", "las", "un", "una", "unos", "unas", "de", "del", "al", "a", "en",
  "con", "por", "para", "sin", "sobre", "y", "o", "u", "e", "es", "son", "se",
  "su", "sus", "mi", "mis", "tu", "tus", "me", "te", "lo", "le", "les", "nos"
]);

const TYPO_DICTIONARY = {
  "kiero": "quiero",
  "conferensias": "conferencias",
  "oy": "hoy",
  "taiyeres": "talleres",
  "tayeres": "talleres",
  "tayer": "taller",
  "piton": "python",
  "phyton": "python",
  "hacka": "hackatec",
  "hakatec": "hackatec",
  "jakatec": "hackatec",
  "hacatec": "hackatec",
  "fut": "futbol",
  "basquet": "basquetbol",
  "voli": "voleibol",
  "volei": "voleibol",
  "kreditos": "creditos",
  "konstancia": "constancia",
  "inscripsion": "inscripcion",
  "ubikacion": "ubicacion",
  "krokis": "croquis",
  "wenas": "buenas",
  "ola": "hola",
  "holaa": "hola",
  "holaaa": "hola",
  "kien": "quien",
  "ke": "que"
};

function normalizeText(str) {
  return str
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function levenshteinDistance(a, b) {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost);
    }
  }
  return dp[m][n];
}

class SalvitaMLClassifier {
  constructor(intentsData) {
    this.intentsData = intentsData;
    this.vocabulary = [];
    this.idf = {};
    this.intentVectors = {};
    this.wordBag = new Set();
    this.train();
  }

  tokenizeAndCorrect(rawText) {
    const norm = normalizeText(rawText);
    if (!norm) return [];
    const rawWords = norm.split(" ");
    const tokens = [];

    for (let w of rawWords) {
      if (w.length <= 1) continue;
      if (TYPO_DICTIONARY[w]) {
        w = TYPO_DICTIONARY[w];
      } else if (w.length >= 5 && this.wordBag.size > 0 && !this.wordBag.has(w)) {
        let bestWord = null;
        let bestDist = 3;
        for (const vocabWord of this.wordBag) {
          if (Math.abs(vocabWord.length - w.length) <= 2 && vocabWord.length >= 5) {
            const d = levenshteinDistance(w, vocabWord);
            if (d < bestDist) {
              bestDist = d;
              bestWord = vocabWord;
            }
          }
        }
        if (bestWord && bestDist <= 2) w = bestWord;
      }
      if (!STOPWORDS_ES.has(w)) tokens.push(w);
    }
    return tokens;
  }

  train() {
    this.wordBag.clear();
    const docTokensList = [];

    this.intentsData.forEach((intentObj) => {
      const combinedText = intentObj.samples.join(" ");
      const normWords = normalizeText(combinedText).split(" ").filter((w) => w.length > 1 && !STOPWORDS_ES.has(w));
      normWords.forEach((w) => this.wordBag.add(w));
      docTokensList.push({ intent: intentObj.intent, tokens: normWords });
    });

    this.vocabulary = Array.from(this.wordBag);
    const N = docTokensList.length;

    this.idf = {};
    this.vocabulary.forEach((term) => {
      let df = 0;
      docTokensList.forEach((doc) => {
        if (doc.tokens.includes(term)) df++;
      });
      this.idf[term] = Math.log((N + 1) / (df + 1)) + 1;
    });

    this.intentVectors = {};
    docTokensList.forEach((doc) => {
      const vec = {};
      const counts = {};
      doc.tokens.forEach((t) => { counts[t] = (counts[t] || 0) + 1; });
      let normSq = 0;
      Object.keys(counts).forEach((t) => {
        const tf = counts[t] / doc.tokens.length;
        const weight = tf * (this.idf[t] || 1);
        vec[t] = weight;
        normSq += weight * weight;
      });
      const mag = Math.sqrt(normSq) || 1;
      Object.keys(vec).forEach((t) => { vec[t] /= mag; });
      this.intentVectors[doc.intent] = vec;
    });
  }

  predict(rawText) {
    const tokens = this.tokenizeAndCorrect(rawText);
    if (tokens.length === 0) return null;

    const qCounts = {};
    tokens.forEach((t) => { qCounts[t] = (qCounts[t] || 0) + 1; });
    const qVec = {};
    let qNormSq = 0;
    Object.keys(qCounts).forEach((t) => {
      const tf = qCounts[t] / tokens.length;
      const idfVal = this.idf[t] || 0.5;
      const w = tf * idfVal;
      qVec[t] = w;
      qNormSq += w * w;
    });
    const qMag = Math.sqrt(qNormSq) || 1;
    Object.keys(qVec).forEach((t) => { qVec[t] /= qMag; });

    let bestIntent = null;
    let bestScore = 0;

    this.intentsData.forEach((intentObj) => {
      const iVec = this.intentVectors[intentObj.intent] || {};
      let dot = 0;
      Object.keys(qVec).forEach((t) => {
        if (iVec[t]) dot += qVec[t] * iVec[t];
      });
      const normInput = tokens.join(" ");
      for (const s of intentObj.samples) {
        const normS = normalizeText(s);
        if (normS === normInput || (normInput.length >= 4 && normS.includes(normInput))) {
          dot = Math.max(dot, 0.94);
        }
      }
      if (dot > bestScore) {
        bestScore = dot;
        bestIntent = intentObj;
      }
    });

    return bestScore >= 0.16 ? bestIntent : null;
  }
}

